SELECT id, customer_id, plan, end_date, monthly_fee, SUM(monthly_fee) OVER (PARTITION BY customer_id, status ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_monthly_fee, ROUND(monthly_fee / SUM(monthly_fee) OVER (PARTITION BY plan, customer_id), 4) AS monthly_fee_share, FIRST_VALUE(monthly_fee) IGNORE NULLS OVER (ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_monthly_fee FROM subscriptions;
